def all_scenes():
    for ep in EPISODES:
        for s in ep["scenes"]:
            yield ep, s
    yield TEASER, None  # marker

if __name__ == "__main__":
    tw = sum(len(s["narration"].split()) for ep in EPISODES for s in ep["scenes"])
    ttw = tw + sum(len(s["narration"].split()) for s in TEASER["scenes"])
    nq = sum(len(s["queries"]) for ep in EPISODES for s in ep["scenes"])
    print(f"episodes words: {tw}  (+teaser {ttw-tw})  total {ttw}")
    print(f"scenes: {sum(len(e['scenes']) for e in EPISODES)} + {len(TEASER['scenes'])} teaser   queries: {nq}")
    for ep in EPISODES:
        print(f"  {ep['folder']}: {sum(len(s['narration'].split()) for s in ep['scenes'])} words, {len(ep['scenes'])} scenes")
